// The console's month and time-of-day background (Month and Time Colors), for
// linkev's wave when the PS3's lines.qrc isn't there: measured from what the
// console's background looks like through the year (every half hour, four
// times a month, 16 x 9), kept as 20 shared pictures and how much of each
// every moment takes. (MaXMB's own measurements; no part of the console's files.)
// monthBackground(month, dayFrac): month 0-12 (with the day: 9.5 is mid-October),
// dayFrac 0-1 (the time of day) -> 16 x 9 RGB (0-255, top row first).

const R = 20, N = 432, T = 48, Q = 48;
const dec = (s) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0)).buffer;
let _m = null;
function model() {
  if (_m) return _m;
  const mu = new Uint16Array(dec(""));
  const bq = new Int16Array(dec(""));
  const cq = new Int8Array(dec(""));
  const bs = [2.12262e-06,2.23041e-06,2.57873e-06,3.17624e-06,2.95309e-06,4.88229e-06,4.99827e-06,4.67338e-06,3.30413e-06,5.1594e-06,4.74724e-06,4.13105e-06,4.45401e-06,3.96504e-06,4.06449e-06,4.81305e-06,4.26418e-06,4.28035e-06,5.15347e-06,5.01595e-06], cs = [12.2592,9.63267,5.79021,5.09558,2.02157,1.7373,2.19345,1.40161,1.84142,0.788272,0.945111,0.730962,0.684247,0.437249,0.412898,0.352577,0.363703,0.278442,0.252168,0.202062];
  const basis = new Float32Array(R * N);
  for (let k = 0; k < R; k++) for (let i = 0; i < N; i++) basis[k * N + i] = bq[k * N + i] * bs[k];
  const coef = new Float32Array(Q * T * R);
  for (let j = 0; j < Q * T; j++) for (let k = 0; k < R; k++) coef[j * R + k] = cq[j * R + k] * cs[k];
  return (_m = { mu: Float32Array.from(mu, (v) => v / 16), basis, coef });
}
export function monthBackground(month, dayFrac) {
  const { mu, basis, coef } = model();
  const q = (((month * 4) % Q) + Q) % Q, q0 = Math.floor(q), fq = q - q0;
  let t = (dayFrac * 1440 - 0.5) / 30; t = ((t % T) + T) % T;
  const t0 = Math.floor(t), ft = t - t0;
  const w = new Float32Array(R);
  const add = (qq, tt, k) => { const j = ((qq % Q) * T + (tt % T)) * R; for (let r = 0; r < R; r++) w[r] += coef[j + r] * k; };
  add(q0, t0, (1 - fq) * (1 - ft)); add(q0 + 1, t0, fq * (1 - ft)); add(q0, t0 + 1, (1 - fq) * ft); add(q0 + 1, t0 + 1, fq * ft);
  const out = new Uint8ClampedArray(N);
  for (let i = 0; i < N; i++) { let v = mu[i]; for (let r = 0; r < R; r++) v += w[r] * basis[r * N + i]; out[i] = Math.round(v); }
  return out;
}
